let words: Set<string> | null = null;

/** Is `word` (lowercase) a common English word? Parses the list on first use. */
export function isCommonEnglishWord(word: string): boolean {
    if (words === null) {
        words = new Set();
        let cur = "";
        for (const m of FRONT_CODED.matchAll(/(\d)([a-z]*)/g)) {
            cur = cur.slice(0, Number(m[1])) + m[2];
            words.add(cur);
        }
    }
    return words.has(word);
}

/** How many words the list holds (for tests). */
export function commonEnglishWordCount(): number {
    isCommonEnglishWord("");
    return words!.size;
}
